function [ok, n, u] = es_sample(u, d, nadir_b)
%ES_SAMPLE  The nadir the sensor gives (body, unit) and whether it gives one, for the true nadir nadir_b (body, unit).
%   u: inout EsUnit (passed rec)
%   d: EsDesc (passed rec)
%   nadir_b: real[1][3] (passed a plain number)
%   returns ok: bool (passed true or false)
%   returns n: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    ok = false;
    n = zeros(3, 1);
    h__702 = acos(asils.models.coilsat.act_clamp((d.bs(1)*nadir_b(1) + d.bs(2)*nadir_b(2) + d.bs(3)*nadir_b(3)), (-(1)), 1));
    if ~isreal(h__702), h__702 = NaN; end
    ok = (~(h__702 >= d.fov));
    n = [0; 0; 0];
    if ok
        g = u.g;
        [t__569, t__570] = asils.pc.stream_normal3(g);
        e0 = t__569;
        g = t__570;
        u.g = g;
        h__703 = asils.models.math.dcm(asils.models.math.qmult(u.bias, asils.models.math.fromrotvec((e0 * d.noise))));
        n = asils.models.facets.unit_or_zero([h__703(1, 1)*nadir_b(1) + h__703(1, 2)*nadir_b(2) + h__703(1, 3)*nadir_b(3); h__703(2, 1)*nadir_b(1) + h__703(2, 2)*nadir_b(2) + h__703(2, 3)*nadir_b(3); h__703(3, 1)*nadir_b(1) + h__703(3, 2)*nadir_b(2) + h__703(3, 3)*nadir_b(3)]);
    end
end
